window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dedbac2a1de8769b"]={"versions": [{"id": "FIG-dedbac2a1de8769b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Strukturelles Architektur- und Allokationsdiagramm / Multicore-Verteilungsdiagramm (BSW Distribution Pattern).\n</li><li><strong>Architektur-Kontext:</strong> Auszug aus dem AUTOSAR-Konzept zur BSW-Verteilung (<code>AUTOSAR_EXP_BSWDistributionGuide</code>). Es visualisiert die Anbindung eines reentranten MCAL-Treibers (DIO) an das verteilte Diagnosesystem über Core-Grenzen hinweg.\n</li><li><strong>Technischer Zweck:</strong> Demonstration des Master-Satellite-Entwurfsmusters des Diagnostic Event Managers (Dem). Ziel ist die strikte Vermeidung von teuren Inter-Core-Cross-Talks (IOC) bei der Fehlerberichterstattung (<code>Dem_SetEventStatus</code>), indem Aufrufer stets den auf demselben Core lokal allokierten Dem-Teil ansprechen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Verarbeitungseinheiten / Partitionen:</strong>\n<ul class=\"fig-list\"><li><code>Core 1</code>: Master-Core, Träger der primären BSW-Infrastruktur.\n</li><li><code>Core 2</code>: Satellite-Core, dedizierter Ausführungskern für Nebenaufgaben/Partitionen.\n</li></ul>\n</li><li><strong>Diagnose-Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>DEM (Master)</code> (Core 1): Vollumfängliche Dem-Instanz; verwaltet den primären Fehlerspeicher (Event Memory, Freeze Frames, Extended Data Records), DTC-Status-Management und Schnittstellen zu Dcm/RTE.\n</li><li><code>DEM (Satellite)</code> (Core 2): Ressourcenoptimierte Dem-Instanz; zuständig für lokale Event-Pufferung, Vorverarbeitung und lokales Event-Debouncing auf Core 2.\n</li></ul>\n</li><li><strong>Treiber-Ebene:</strong>\n<ul class=\"fig-list\"><li><code>DIO</code> (Digital Input/Output Driver, MCAL): Reentrant implementiertes Treibermodul, das als gemeinsame funktionale Entität auf beiden Cores ausgeführt werden kann.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>API: Standardisierte C-Schnittstelle <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code>.\n</li><li>Core 1: <code>Dem_SetEventStatus(7, status)</code> mit statischer <code>Dem_EventIdType = 7</code> (konfiguriert für den Dem Master).\n</li><li>Core 2: <code>Dem_SetEventStatus(6, status)</code> mit statischer <code>Dem_EventIdType = 6</code> (konfiguriert für den Dem Satellite).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Fehlererkennung auf Core 1:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 1 ausgeführte DIO-Routine erkennt eine Fehlbedingung (z. B. Readback-Fehler oder Konfigurationsinkonsistenz).\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(7, status)</code>.\n</li><li>Ausführung erfolgt direkt im Kontext des lokalen <code>DEM (Master)</code> ohne Core-Wechsel.\n</li></ul>\n</li><li><strong>Fehlererkennung auf Core 2:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 2 ausgeführte DIO-Routine detektiert einen Fehler.\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(6, status)</code>.\n</li><li>Ausführung verbleibt strikt lokal im Stack-Kontext des <code>DEM (Satellite)</code>.\n</li></ul>\n</li><li><strong>Interne Kaskadierung / Asynchrone Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Der <code>DEM (Satellite)</code> verarbeitet den Statuswechsel lokal (z. B. zähler- oder zeitbasiertes Debouncing).\n</li><li>Bei Zustandsänderung (z. B. Event <code>PASSED</code> → <code>FAILED</code>) meldet der Satellit das Ergebnis asynchron (typischerweise über OS Inter-OS-Application-Calls bzw. IOC / SchM) an den <code>DEM (Master)</code> zur Persistierung im NVRAM und zur Aktualisierung des UDS-DTC-Status.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Event-ID-Allokation (<code>DemEventParameter</code>):</strong>\n<ul class=\"fig-list\"><li>Dem-Ereignisse müssen im EcuC/ARXML-Modell explizit dem Master bzw. einem spezifischen Satellite-Core zugewiesen werden (<code>DemSatelliteId</code>-Referenz).\n</li><li>Tritt derselbe logische Hardware-Fehler auf unterschiedlichen Cores auf, müssen im MCAL getrennte Dem-Event-IDs (hier ID <code>7</code> und <code>6</code>) konfiguriert und codeseitig unterschieden werden.\n</li></ul>\n</li><li><strong>Treiber-Reentranz (<code>DIO</code>):</strong>\n<ul class=\"fig-list\"><li>DIO-Funktionen müssen thread-sicher und reentrant ausgelegt sein (<code>DIO_IS_REENTRANT == TRUE</code>).\n</li><li>Da MCAL-Treiber üblicherweise keinen dynamischen Core-Lookup zur Laufzeit (<code>GetCoreID()</code>) innerhalb zeitkritischer Pfade durchführen sollen, steuern applikative Zuordnung oder Core-spezifische Channel-Mappings, welche Event-ID übergeben wird.\n</li></ul>\n</li><li><strong>Laufzeit- und Latenz-Optimierung:</strong>\n<ul class=\"fig-list\"><li>Der direkte synchrone Aufruf in den lokalen Satelliten verhindert Inter-Core-Interrupts (IPI) und blockierende Spinlocks innerhalb des Treibers.\n</li><li>Entwickler müssen sicherstellen, dass auf Core 2 ausschließlich der Header des Dem-Satelliten bzw. die generierte, Core-lokale BSW-Schnittstelle eingebunden wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5fb8954f08534576", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Strukturelles Architektur- und Allokationsdiagramm / Multicore-Verteilungsdiagramm (BSW Distribution Pattern).\n</li><li><strong>Architektur-Kontext:</strong> Auszug aus dem AUTOSAR-Konzept zur BSW-Verteilung (<code>AUTOSAR_EXP_BSWDistributionGuide</code>). Es visualisiert die Anbindung eines reentranten MCAL-Treibers (DIO) an das verteilte Diagnosesystem über Core-Grenzen hinweg.\n</li><li><strong>Technischer Zweck:</strong> Demonstration des Master-Satellite-Entwurfsmusters des Diagnostic Event Managers (Dem). Ziel ist die strikte Vermeidung von teuren Inter-Core-Cross-Talks (IOC) bei der Fehlerberichterstattung (<code>Dem_SetEventStatus</code>), indem Aufrufer stets den auf demselben Core lokal allokierten Dem-Teil ansprechen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Verarbeitungseinheiten / Partitionen:</strong>\n<ul class=\"fig-list\"><li><code>Core 1</code>: Master-Core, Träger der primären BSW-Infrastruktur.\n</li><li><code>Core 2</code>: Satellite-Core, dedizierter Ausführungskern für Nebenaufgaben/Partitionen.\n</li></ul>\n</li><li><strong>Diagnose-Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>DEM (Master)</code> (Core 1): Vollumfängliche Dem-Instanz; verwaltet den primären Fehlerspeicher (Event Memory, Freeze Frames, Extended Data Records), DTC-Status-Management und Schnittstellen zu Dcm/RTE.\n</li><li><code>DEM (Satellite)</code> (Core 2): Ressourcenoptimierte Dem-Instanz; zuständig für lokale Event-Pufferung, Vorverarbeitung und lokales Event-Debouncing auf Core 2.\n</li></ul>\n</li><li><strong>Treiber-Ebene:</strong>\n<ul class=\"fig-list\"><li><code>DIO</code> (Digital Input/Output Driver, MCAL): Reentrant implementiertes Treibermodul, das als gemeinsame funktionale Entität auf beiden Cores ausgeführt werden kann.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>API: Standardisierte C-Schnittstelle <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code>.\n</li><li>Core 1: <code>Dem_SetEventStatus(7, status)</code> mit statischer <code>Dem_EventIdType = 7</code> (konfiguriert für den Dem Master).\n</li><li>Core 2: <code>Dem_SetEventStatus(6, status)</code> mit statischer <code>Dem_EventIdType = 6</code> (konfiguriert für den Dem Satellite).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Fehlererkennung auf Core 1:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 1 ausgeführte DIO-Routine erkennt eine Fehlbedingung (z. B. Readback-Fehler oder Konfigurationsinkonsistenz).\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(7, status)</code>.\n</li><li>Ausführung erfolgt direkt im Kontext des lokalen <code>DEM (Master)</code> ohne Core-Wechsel.\n</li></ul>\n</li><li><strong>Fehlererkennung auf Core 2:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 2 ausgeführte DIO-Routine detektiert einen Fehler.\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(6, status)</code>.\n</li><li>Ausführung verbleibt strikt lokal im Stack-Kontext des <code>DEM (Satellite)</code>.\n</li></ul>\n</li><li><strong>Interne Kaskadierung / Asynchrone Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Der <code>DEM (Satellite)</code> verarbeitet den Statuswechsel lokal (z. B. zähler- oder zeitbasiertes Debouncing).\n</li><li>Bei Zustandsänderung (z. B. Event <code>PASSED</code> → <code>FAILED</code>) meldet der Satellit das Ergebnis asynchron (typischerweise über OS Inter-OS-Application-Calls bzw. IOC / SchM) an den <code>DEM (Master)</code> zur Persistierung im NVRAM und zur Aktualisierung des UDS-DTC-Status.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Event-ID-Allokation (<code>DemEventParameter</code>):</strong>\n<ul class=\"fig-list\"><li>Dem-Ereignisse müssen im EcuC/ARXML-Modell explizit dem Master bzw. einem spezifischen Satellite-Core zugewiesen werden (<code>DemSatelliteId</code>-Referenz).\n</li><li>Tritt derselbe logische Hardware-Fehler auf unterschiedlichen Cores auf, müssen im MCAL getrennte Dem-Event-IDs (hier ID <code>7</code> und <code>6</code>) konfiguriert und codeseitig unterschieden werden.\n</li></ul>\n</li><li><strong>Treiber-Reentranz (<code>DIO</code>):</strong>\n<ul class=\"fig-list\"><li>DIO-Funktionen müssen thread-sicher und reentrant ausgelegt sein (<code>DIO_IS_REENTRANT == TRUE</code>).\n</li><li>Da MCAL-Treiber üblicherweise keinen dynamischen Core-Lookup zur Laufzeit (<code>GetCoreID()</code>) innerhalb zeitkritischer Pfade durchführen sollen, steuern applikative Zuordnung oder Core-spezifische Channel-Mappings, welche Event-ID übergeben wird.\n</li></ul>\n</li><li><strong>Laufzeit- und Latenz-Optimierung:</strong>\n<ul class=\"fig-list\"><li>Der direkte synchrone Aufruf in den lokalen Satelliten verhindert Inter-Core-Interrupts (IPI) und blockierende Spinlocks innerhalb des Treibers.\n</li><li>Entwickler müssen sicherstellen, dass auf Core 2 ausschließlich der Header des Dem-Satelliten bzw. die generierte, Core-lokale BSW-Schnittstelle eingebunden wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-735d406deed6ce52", "releases": ["R20-11", "R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Strukturelles Architektur- und Allokationsdiagramm / Multicore-Verteilungsdiagramm (BSW Distribution Pattern).\n</li><li><strong>Architektur-Kontext:</strong> Auszug aus dem AUTOSAR-Konzept zur BSW-Verteilung (<code>AUTOSAR_EXP_BSWDistributionGuide</code>). Es visualisiert die Anbindung eines reentranten MCAL-Treibers (DIO) an das verteilte Diagnosesystem über Core-Grenzen hinweg.\n</li><li><strong>Technischer Zweck:</strong> Demonstration des Master-Satellite-Entwurfsmusters des Diagnostic Event Managers (Dem). Ziel ist die strikte Vermeidung von teuren Inter-Core-Cross-Talks (IOC) bei der Fehlerberichterstattung (<code>Dem_SetEventStatus</code>), indem Aufrufer stets den auf demselben Core lokal allokierten Dem-Teil ansprechen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Verarbeitungseinheiten / Partitionen:</strong>\n<ul class=\"fig-list\"><li><code>Core 1</code>: Master-Core, Träger der primären BSW-Infrastruktur.\n</li><li><code>Core 2</code>: Satellite-Core, dedizierter Ausführungskern für Nebenaufgaben/Partitionen.\n</li></ul>\n</li><li><strong>Diagnose-Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>DEM (Master)</code> (Core 1): Vollumfängliche Dem-Instanz; verwaltet den primären Fehlerspeicher (Event Memory, Freeze Frames, Extended Data Records), DTC-Status-Management und Schnittstellen zu Dcm/RTE.\n</li><li><code>DEM (Satellite)</code> (Core 2): Ressourcenoptimierte Dem-Instanz; zuständig für lokale Event-Pufferung, Vorverarbeitung und lokales Event-Debouncing auf Core 2.\n</li></ul>\n</li><li><strong>Treiber-Ebene:</strong>\n<ul class=\"fig-list\"><li><code>DIO</code> (Digital Input/Output Driver, MCAL): Reentrant implementiertes Treibermodul, das als gemeinsame funktionale Entität auf beiden Cores ausgeführt werden kann.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>API: Standardisierte C-Schnittstelle <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code>.\n</li><li>Core 1: <code>Dem_SetEventStatus(7, status)</code> mit statischer <code>Dem_EventIdType = 7</code> (konfiguriert für den Dem Master).\n</li><li>Core 2: <code>Dem_SetEventStatus(6, status)</code> mit statischer <code>Dem_EventIdType = 6</code> (konfiguriert für den Dem Satellite).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Fehlererkennung auf Core 1:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 1 ausgeführte DIO-Routine erkennt eine Fehlbedingung (z. B. Readback-Fehler oder Konfigurationsinkonsistenz).\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(7, status)</code>.\n</li><li>Ausführung erfolgt direkt im Kontext des lokalen <code>DEM (Master)</code> ohne Core-Wechsel.\n</li></ul>\n</li><li><strong>Fehlererkennung auf Core 2:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 2 ausgeführte DIO-Routine detektiert einen Fehler.\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(6, status)</code>.\n</li><li>Ausführung verbleibt strikt lokal im Stack-Kontext des <code>DEM (Satellite)</code>.\n</li></ul>\n</li><li><strong>Interne Kaskadierung / Asynchrone Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Der <code>DEM (Satellite)</code> verarbeitet den Statuswechsel lokal (z. B. zähler- oder zeitbasiertes Debouncing).\n</li><li>Bei Zustandsänderung (z. B. Event <code>PASSED</code> → <code>FAILED</code>) meldet der Satellit das Ergebnis asynchron (typischerweise über OS Inter-OS-Application-Calls bzw. IOC / SchM) an den <code>DEM (Master)</code> zur Persistierung im NVRAM und zur Aktualisierung des UDS-DTC-Status.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Event-ID-Allokation (<code>DemEventParameter</code>):</strong>\n<ul class=\"fig-list\"><li>Dem-Ereignisse müssen im EcuC/ARXML-Modell explizit dem Master bzw. einem spezifischen Satellite-Core zugewiesen werden (<code>DemSatelliteId</code>-Referenz).\n</li><li>Tritt derselbe logische Hardware-Fehler auf unterschiedlichen Cores auf, müssen im MCAL getrennte Dem-Event-IDs (hier ID <code>7</code> und <code>6</code>) konfiguriert und codeseitig unterschieden werden.\n</li></ul>\n</li><li><strong>Treiber-Reentranz (<code>DIO</code>):</strong>\n<ul class=\"fig-list\"><li>DIO-Funktionen müssen thread-sicher und reentrant ausgelegt sein (<code>DIO_IS_REENTRANT == TRUE</code>).\n</li><li>Da MCAL-Treiber üblicherweise keinen dynamischen Core-Lookup zur Laufzeit (<code>GetCoreID()</code>) innerhalb zeitkritischer Pfade durchführen sollen, steuern applikative Zuordnung oder Core-spezifische Channel-Mappings, welche Event-ID übergeben wird.\n</li></ul>\n</li><li><strong>Laufzeit- und Latenz-Optimierung:</strong>\n<ul class=\"fig-list\"><li>Der direkte synchrone Aufruf in den lokalen Satelliten verhindert Inter-Core-Interrupts (IPI) und blockierende Spinlocks innerhalb des Treibers.\n</li><li>Entwickler müssen sicherstellen, dass auf Core 2 ausschließlich der Header des Dem-Satelliten bzw. die generierte, Core-lokale BSW-Schnittstelle eingebunden wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-6f472a5cbd927501", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Strukturelles Architektur- und Allokationsdiagramm / Multicore-Verteilungsdiagramm (BSW Distribution Pattern).\n</li><li><strong>Architektur-Kontext:</strong> Auszug aus dem AUTOSAR-Konzept zur BSW-Verteilung (<code>AUTOSAR_EXP_BSWDistributionGuide</code>). Es visualisiert die Anbindung eines reentranten MCAL-Treibers (DIO) an das verteilte Diagnosesystem über Core-Grenzen hinweg.\n</li><li><strong>Technischer Zweck:</strong> Demonstration des Master-Satellite-Entwurfsmusters des Diagnostic Event Managers (Dem). Ziel ist die strikte Vermeidung von teuren Inter-Core-Cross-Talks (IOC) bei der Fehlerberichterstattung (<code>Dem_SetEventStatus</code>), indem Aufrufer stets den auf demselben Core lokal allokierten Dem-Teil ansprechen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Verarbeitungseinheiten / Partitionen:</strong>\n<ul class=\"fig-list\"><li><code>Core 1</code>: Master-Core, Träger der primären BSW-Infrastruktur.\n</li><li><code>Core 2</code>: Satellite-Core, dedizierter Ausführungskern für Nebenaufgaben/Partitionen.\n</li></ul>\n</li><li><strong>Diagnose-Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>DEM (Master)</code> (Core 1): Vollumfängliche Dem-Instanz; verwaltet den primären Fehlerspeicher (Event Memory, Freeze Frames, Extended Data Records), DTC-Status-Management und Schnittstellen zu Dcm/RTE.\n</li><li><code>DEM (Satellite)</code> (Core 2): Ressourcenoptimierte Dem-Instanz; zuständig für lokale Event-Pufferung, Vorverarbeitung und lokales Event-Debouncing auf Core 2.\n</li></ul>\n</li><li><strong>Treiber-Ebene:</strong>\n<ul class=\"fig-list\"><li><code>DIO</code> (Digital Input/Output Driver, MCAL): Reentrant implementiertes Treibermodul, das als gemeinsame funktionale Entität auf beiden Cores ausgeführt werden kann.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>API: Standardisierte C-Schnittstelle <code>Std_ReturnType Dem_SetEventStatus(Dem_EventIdType EventId, Dem_EventStatusType EventStatus)</code>.\n</li><li>Core 1: <code>Dem_SetEventStatus(7, status)</code> mit statischer <code>Dem_EventIdType = 7</code> (konfiguriert für den Dem Master).\n</li><li>Core 2: <code>Dem_SetEventStatus(6, status)</code> mit statischer <code>Dem_EventIdType = 6</code> (konfiguriert für den Dem Satellite).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Fehlererkennung auf Core 1:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 1 ausgeführte DIO-Routine erkennt eine Fehlbedingung (z. B. Readback-Fehler oder Konfigurationsinkonsistenz).\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(7, status)</code>.\n</li><li>Ausführung erfolgt direkt im Kontext des lokalen <code>DEM (Master)</code> ohne Core-Wechsel.\n</li></ul>\n</li><li><strong>Fehlererkennung auf Core 2:</strong>\n<ul class=\"fig-list\"><li>Eine auf Core 2 ausgeführte DIO-Routine detektiert einen Fehler.\n</li><li>Synchroner Aufruf von <code>Dem_SetEventStatus(6, status)</code>.\n</li><li>Ausführung verbleibt strikt lokal im Stack-Kontext des <code>DEM (Satellite)</code>.\n</li></ul>\n</li><li><strong>Interne Kaskadierung / Asynchrone Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Der <code>DEM (Satellite)</code> verarbeitet den Statuswechsel lokal (z. B. zähler- oder zeitbasiertes Debouncing).\n</li><li>Bei Zustandsänderung (z. B. Event <code>PASSED</code> → <code>FAILED</code>) meldet der Satellit das Ergebnis asynchron (typischerweise über OS Inter-OS-Application-Calls bzw. IOC / SchM) an den <code>DEM (Master)</code> zur Persistierung im NVRAM und zur Aktualisierung des UDS-DTC-Status.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Event-ID-Allokation (<code>DemEventParameter</code>):</strong>\n<ul class=\"fig-list\"><li>Dem-Ereignisse müssen im EcuC/ARXML-Modell explizit dem Master bzw. einem spezifischen Satellite-Core zugewiesen werden (<code>DemSatelliteId</code>-Referenz).\n</li><li>Tritt derselbe logische Hardware-Fehler auf unterschiedlichen Cores auf, müssen im MCAL getrennte Dem-Event-IDs (hier ID <code>7</code> und <code>6</code>) konfiguriert und codeseitig unterschieden werden.\n</li></ul>\n</li><li><strong>Treiber-Reentranz (<code>DIO</code>):</strong>\n<ul class=\"fig-list\"><li>DIO-Funktionen müssen thread-sicher und reentrant ausgelegt sein (<code>DIO_IS_REENTRANT == TRUE</code>).\n</li><li>Da MCAL-Treiber üblicherweise keinen dynamischen Core-Lookup zur Laufzeit (<code>GetCoreID()</code>) innerhalb zeitkritischer Pfade durchführen sollen, steuern applikative Zuordnung oder Core-spezifische Channel-Mappings, welche Event-ID übergeben wird.\n</li></ul>\n</li><li><strong>Laufzeit- und Latenz-Optimierung:</strong>\n<ul class=\"fig-list\"><li>Der direkte synchrone Aufruf in den lokalen Satelliten verhindert Inter-Core-Interrupts (IPI) und blockierende Spinlocks innerhalb des Treibers.\n</li><li>Entwickler müssen sicherstellen, dass auf Core 2 ausschließlich der Header des Dem-Satelliten bzw. die generierte, Core-lokale BSW-Schnittstelle eingebunden wird.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-dedbac2a1de8769b", "to": "FIG-5fb8954f08534576", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>API-Beschriftungen</code>: Schriftart der Funktionsaufrufe <code>Dem_SetEventStatus(7, status)</code> und <code>Dem_SetEventStatus(6, status)</code> auf Monospace umgestellt.\n</li><li><code>Layout</code>: Fehlerhafte Textüberlagerung der beiden API-Signaturen im Zwischenraum der Verbindungspfeile infolge veränderter Schriftbreite; oberer Rand der Partitionen <code>Core 1</code> und <code>Core 2</code> beschnitten.\n</li></ul>"}, {"from": "FIG-5fb8954f08534576", "to": "FIG-735d406deed6ce52", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Layout</code>: Fehlerhafte Textüberlagerung korrigiert; die API-Aufrufe <code>Dem_SetEventStatus(7, status)</code> und <code>Dem_SetEventStatus(6, status)</code> sind wieder getrennt und überdeckungsfrei ausgerichtet.\n</li><li><code>Partitionen</code>: Oberer Randabstand über <code>Core 1</code> und <code>Core 2</code> wiederhergestellt.\n</li></ul>"}, {"from": "FIG-735d406deed6ce52", "to": "FIG-6f472a5cbd927501", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
